// Package main — the generated files' digests against the design files.
package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// kitFile writes a generated file whose header names design and carries the
// digests of designBytes and of body, as kit writes it.
func kitFile(design string, designBytes []byte, body string) string {
	return kitHeaderPrefix + design + " (sha256 " + sha256Hex(designBytes) + ", body " + sha256Hex([]byte(body)) + "). DO NOT EDIT.\n" + body
}

// Test_digestFindings pins every finding the digests give, each by its name:
// a design byte changed without kit gen, a body edited by hand, a design
// file missing, a design file named outside the repository, a pin file or a
// port file without a kit header; a file whose digests hold gives none, and
// neither does a hand-written file.
func Test_digestFindings(t *testing.T) {
	t.Parallel()
	design := []byte("domain: app/lock\n")
	body := "\npackage lock_test\n"
	type tc struct {
		// name describes the case.
		name string
		// files are staged in the package's directory.
		files map[string]string
		// designOnDisk is the design file's content, or nil for none.
		designOnDisk []byte
		// want are the findings' fragments; none when the digests hold.
		want []string
	}
	tests := []tc{
		{
			name:         "a pin and a port whose digests hold",
			files:        map[string]string{"api_gen_test.go": kitFile("design/app/lock.yaml", design, body), "design_gen.go": kitFile("design/app/lock.yaml", design, "\npackage lock\n"), "lock.go": "package lock\n"},
			designOnDisk: design,
		},
		{
			name:         "a design edit without kit gen",
			files:        map[string]string{"api_gen_test.go": kitFile("design/app/lock.yaml", design, body)},
			designOnDisk: []byte("domain: app/lock\n# edited\n"),
			want:         []string{"design file changed: design/app/lock.yaml hashes to"},
		},
		{
			name:         "a body edited by hand",
			files:        map[string]string{"api_gen_test.go": kitFile("design/app/lock.yaml", design, body) + "// edited\n"},
			designOnDisk: design,
			want:         []string{"body edited: its body hashes to"},
		},
		{
			name:  "a design file that is gone",
			files: map[string]string{"api_gen_test.go": kitFile("design/app/lock.yaml", design, body)},
			want:  []string{"design file missing: design/app/lock.yaml does not exist"},
		},
		{
			name:         "a design file outside the repository",
			files:        map[string]string{"api_gen_test.go": kitFile("../design/app/lock.yaml", design, body)},
			designOnDisk: design,
			want:         []string{"names a design file outside the repository"},
		},
		{
			name:  "a pin file without a header",
			files: map[string]string{"api_gen_test.go": "package lock_test\n"},
			want:  []string{"no kit header"},
		},
		{
			name:  "a port file whose header is another tool's",
			files: map[string]string{"design_gen.go": "// Code generated by stringer. DO NOT EDIT.\npackage lock\n"},
			want:  []string{"no kit header"},
		},
	}
	runCase := func(t *testing.T, c tc) {
		t.Helper()
		root := t.TempDir()
		dir := filepath.Join(root, "internal", "core", "app", "lock")
		stage(t, dir, c.files)
		if c.designOnDisk != nil {
			stage(t, filepath.Join(root, "design", "app"), map[string]string{"lock.yaml": string(c.designOnDisk)})
		}

		got := digestFindings(root, []packageDir{{dir: dir, path: "example.com/lock"}})

		if len(got) != len(c.want) {
			t.Fatalf("findings = %q, want %d", got, len(c.want))
		}
		for i, f := range got {
			if !strings.Contains(f, c.want[i]) || !strings.HasPrefix(f, "internal/core/app/lock/") {
				t.Fatalf("finding %d = %q, want it at its file and to contain %q", i, f, c.want[i])
			}
		}
	}
	for _, c := range tests {
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			runCase(t, c)
		})
	}
}

// stage writes files into dir, creating it.
func stage(t *testing.T, dir string, files map[string]string) {
	t.Helper()
	if err := os.MkdirAll(dir, 0o750); err != nil {
		t.Fatalf("staging %s: %v", dir, err)
	}
	for name, src := range files {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(src), 0o600); err != nil {
			t.Fatalf("staging %s: %v", name, err)
		}
	}
}
